{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C10"],
      "claim": "In baboons, [18F]ketanserin showed rapid and sustained brain uptake, directly demonstrating that the 4-halobenzoylpiperidine core is CNS-penetrant; the query shares this core.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "[18F]altanserin, a close analogue with the same 4-fluorobenzoylpiperidine scaffold, showed sufficient brain uptake in rats by micro-PET, supporting meaningful CNS access for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "FBMV, a fluorobenzoyl-containing CNS tracer with a phenylpiperidine and hydroxyl motif, showed desirable brain uptake in pigs, supporting the query's similar aryl-carbonyl piperidine and tetralinol features.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "The thioether-containing basic amine SIB-1553A showed sufficient rat brain uptake, supporting that the fluoroethylthio ether and basic piperidine in the query do not preclude BBB penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "A benzamide bearing a 1-benzyl-4-piperidinyl group showed significant, lasting high brain uptake in mice, supporting the aryl-carbonyl piperidine chemotype as CNS-penetrant.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "R-licarbazepine had a brain/plasma ratio of 0.05-0.50 in mice, indicating restricted brain entry, but its tricyclic carboxamide structure is dissimilar and this negative result transfers weakly to the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C08"],
      "claim": "3-[18F]FEPB showed low non-receptor-mediated brain uptake in rodents, but its tropane ester scaffold is structurally distant from the query's aryl ketone piperidine, limiting its relevance.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Pass. The highest-transfer analogues (ketanserin, altanserin, FBMV) are direct in vivo CNS-penetrant tracers sharing the aryl-carbonyl piperidine core; additional thioether/piperidine and benzylpiperidine analogues show robust brain uptake. The query's low TPSA, moderate logD, and single HBD support meaningful BBB access despite partial ionization and possible efflux liability. Negative analogues are structurally more distant and do not override the transferable positive evidence.",
  "evidence_gaps": [
    "No direct brain/plasma or PET measurement for the exact query molecule",
    "P-gp/BCRP efflux liability not experimentally assessed",
    "Stereochemistry of the tetralinol/piperidine substituent is unspecified",
    "Thioether metabolism may alter in vivo exposure but does not directly define BBB penetration"
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

